namespace ArcaSim.Application.Services.Mtxca;

/// <summary>Which table of the manual a code comes from: error and observation numbers are separate spaces, and each method has its own.</summary>
public enum MtxcaTable
{
    /// <summary>autorizarComprobante, plus the issuer's checks (pág. 16).</summary>
    Cae,

    /// <summary>informarComprobanteCAEA.</summary>
    Caea,

    /// <summary>solicitarCAEA, plus the issuer's checks.</summary>
    Request,

    /// <summary>informarCAEANoUtilizado and informarCAEANoUtilizadoPtoVta.</summary>
    Unused,

    /// <summary>The queries: consultarCAEA, consultarCAEAEntreFechas, consultarUltimoComprobanteAutorizado, consultarComprobante, consultarCondicionesIVAReceptor, consultarCotizacionMoneda.</summary>
    Query,
}

/// <summary>One code a validation produced: an error that rejects, or an observation that lets the voucher through.</summary>
public sealed record MtxcaFinding(int Code, string Text, bool Rejects);

/// <summary>
/// The codes ArcaSim's wsmtxca rules use, with the manual's text for each
/// (docs/arca/servicios/wsmtxca-codigos.json). The manual prints the condition
