        [(Caea, 195, true)] = "No es posible indicar una cotización negativa",
        [(Caea, 708, false)] = "Si <codigoTipoDocumento> es igual a 80, 86 o 87, <numeroDocumento> debe ser válido y activo, excepto para <codigoTipoComprobante> 6, 7 u 8, <codigoTipoDocumento> 80 y <numeroDocumento> igual a 23000000000.",
        [(Caea, 717, false)] = "No debe estar informado como CAEA No utilizado",
        [(Caea, 719, false)] = "Si <codigoTipoComprobante> es igual a 1, 2, 3, 51, 52 o 53: - Deberá ser igual a la sumatoria de importeItem menos importeIVA para los ítems con <codigoCondicionIVA> igual a 3, 4, 5, 6. Si <codigoTipoComprobante> es igual a 6, 7 u 8: - Deberá ser igual a la sumatoria de <importeItem> menos el IVA correspondiente (calculado en base al importe y la alícuota de cada ítem), para la totalidad de los ítems con <codigoCondicionIVA> igual a 3, 4, 5 ó 6. Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 * cantidad de ítems gravados *",
        [(Caea, 720, false)] = "Deberá coincidir con la sumatoria de <importeItem> para los ítems con <codigoCondicionIVA> igual a 1. Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 * cantidad de ítems no gravados *",
        [(Caea, 721, false)] = "Deberá coincidir con la sumatoria de <importeItem> para los ítems con <codigoCondicionIVA> igual a 2. Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 * cantidad de ítems exentos *",
        [(Caea, 722, false)] = "Deberá coincidir con la sumatoria de los campos <importeNoGravado>, <importeGravado>, <importeExento>. Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 *",
        [(Caea, 723, false)] = "Debe ser igual a la sumatoria de la totalidad de los campos <importe><otroTributo> (dentro de <arrayOtrosTributos>). Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 * cantidad de tributos *",
        [(Caea, 724, false)] = "Debe ser igual a <importeSubtotal>+ <importeOtrosTributos> + sumatoria de <subtotalIVA><importe> (dentro del arraySubtotalesIVA). Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 *",
        [(Caea, 725, false)] = "Debe ser igual a <importeOtrosTributos> + la sumatoria de la totalidad de los campos <importeItem>. Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 * cantidad de ítems *",
        [(Caea, 122, false)] = "En caso de enviar la marca de que el pago del comprobante se realiza en la misma moneda extranjera para comprobantes que no sean facturas. Unicamente se puede utilizar con los códigos habilitados (1,6,51,201,206)",
        [(Caea, 182, false)] = "No podrá ser inferior al 2% ni superior en un 400% del que suministra ARCA como orientativo de acuerdo a la cotización oficial",
        [(Caea, 726, false)] = "Debe ser igual a 1 (uno) si <codigoMoneda> es igual a PES",
        [(Caea, 174, false)] = "En caso de enviar un valor inválido para la marca de que el pago de la factura se realiza en la misma moneda extranjera. Los valores válidos son S, N o vacío",
        [(Caea, 175, false)] = "En caso de enviar la marca de que el pago de la factura se realiza en la misma moneda extranjera y enviar como código de moneda el Peso Argentino",
        [(Caea, 727, false)] = "Debe informarse solo si <codigoConcepto> es igual a 2 ó 3. En otro caso no corresponde.",
        [(Caea, 728, false)] = "Debe informarse solo si <codigoConcepto> es igual a 2 ó 3. En otro caso no corresponde.",
        [(Caea, 729, false)] = "Debe informarse solo si <codigoConcepto> es igual a 2 ó 3. En otro caso no corresponde.",
        [(Caea, 730, false)] = "La fecha de vencimiento de pago debe ser mayor o igual a la fecha de emisión.",
        [(Caea, 734, false)] = "Si <codigoTipoComprobante> es igual a 1, 2, 3, 51, 52 o 53 la CUIT del receptor debe encontrarse activa en IVA o en monotributo.",
        [(Caea, 735, false)] = "El Receptor no puede ser igual al Emisor",
        [(Caea, 737, false)] = "La Fecha de Servicio desde debe ser menor o igual a la Fecha de Servicio Hasta",
        [(Caea, 749, false)] = "Falta incluir en la sección OtrosTributos la Percepción de IVA No Categorizado (ID 13), según lo dispuesto por la RG 2126/2006. Se debe informar el tributo <codigo> 13 (Percepción de IVA No Categorizado) con un <importe> mayor a 0 (cero) dentro del nodo <arrayOtrosTributos> cuando se cumplan simultáneamente las siguientes condiciones: - <codigoTipoComprobante> corresponda a un comprobante clase B (6, 7 u 8). - <codigoTipoDocumento> sea igual a 80 (CUIT). - <numeroDocumento> corresponda a 23000000000 (No Categorizado). - La suma de <importeGravado> más la sumatoria de los campos <importe> dentro de <arraySubtotalesIVA> sea mayor a 0 (cero).",
        [(Caea, 750, false)] = "Debe estar dado de alta en el Impuesto al Valor Agregado al momento de la fecha de emisión del comprobante",
        [(Caea, 782, false)] = "Si <codigoTipoComprobante> es igual a 1, 2, 3, 51, 52 ó 53 la CUIT del receptor es activa en monotributo",
        [(Caea, 366, false)] = "Si <codigo> se encuentra mas de una vez en el array de actividades (no admite repetidos). Ver el Anexo de Rubros de Actividades y Remitos",
        [(Caea, 367, false)] = "Si <codigo> no se encuentra entre las actividades vigentes para la cuit representada. Ver el Anexo de Rubros de Actividades y Remitos",
        [(Caea, 390, false)] = "Si no se informa la condición de IVA del Receptor (obligatoria) o bien se informa un valor no contemplado por el servicio. Ver método consultarCondicionesIVARecep tor",
        [(Caea, 391, false)] = "A partir del 5 de abril de 2025 podrá enviarse de forma opcional el campo Condición Frente al IVA del receptor, hasta tanto entre en vigencia su obligatoriedad reglamentada por la Resolución General N° 5616, en cuyo momento pasará a rechazar la emisión de comprobantes sin este dato. Si se informa una combinación invalida de Condición de IVA del Receptor y Tipo de Comprobante. Ver método consultarCondicionesIVARecep tor",
        [(Caea, 1001, false)] = "Para comprobantes clase “A”: Deberá coincidir con la sumatoria de todos los <importeIVA> de <item> donde la alícuota de IVA coincida con la indicada, es decir, donde <codigoCondicionIVA> de <item> = <codigo> de <subtotalIVA>. Para comprobantes clase “B”: Deberá coincidir con la sumatoria de todos los importes IVA calculados en base al importe y alícuota IVA de <item> donde la alícuota de IVA coincida con la indicada, es decir, donde <codigoCondicionIVA> de <item> = <codigo> de <subtotalIVA>. Margen de error: Error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 * cantidad de ítems con igual código de alícuota de IVA *",
        [(Caea, 1005, false)] = "La suma de los subtotales de IVA no puede ser negativa.",
        [(Caea, 1114, false)] = "De informarse deberá ser menor o igual a <precioUnitario>*<cantidad>",
        [(Caea, 1115, false)] = "Si <codigoUnidadMedida> es 99 deberá existir por lo menos otro item con igual <codigoCondicionIVA> y <codigoUnidadMedida> distinta a la informada para este item.",
        [(Caea, 1116, false)] = "Para <codigoTipoComprobante> igual a 1, 2, 3, 51, 52 o 53 y unidad de medida es distinto a 95, 97 o 99 deberá ser igual (<precioUnitario> * <cantidad> -<importeBonificación>) * alícuota de IVA correspondiente. Para <codigoTipoComprobante> igual a 1, 2, 3, 51, 52 o 53 y unidad de medida igual a 95 deberá ser igual a (-1) * (<precioUnitario> * <cantidad> - <importeBonificacion>) * alícuota de IVA correspondiente. Para <codigoTipoComprobante> igual a 1, 2, 3, 51, 52 o 53 y unidad de medida igual a 97 o 99, deberá ser igual a <importeItem> - <importeItem> / (1 + alícuota de IVA correspondiente).",
        [(Caea, 1117, false)] = "Si <codigoTipoComprobante> es igual a 1, 2 ó 3 y <codigoUnidadMedida> es 99, el valor absoluto de la sumatoria de los importes ingresados para este campo no puede superar a la sumatoria de los importes <importeIVA> informado con la misma alícuota.",
        [(Caea, 1118, false)] = "Si <codigoTipoComprobante> es igual a 1, 2, 3, 51, 52 o 53 y <codigoUnidadMedida> es: - 99 deberá ser menor o igual a 0 (cero), - 97 podrá ser menor, mayor o igual a 0 (cero). - 95 deberá ser menor o igual a 0 (cero), - Cualquier otro caso deberá ser mayor o igual a 0 (cero)",
        [(Caea, 1119, false)] = "Si <codigoUnidadMedida> es: - 99 deberá ser menor a 0 (cero), - 97 podrá ser menor, mayor o igual a 0 (cero) - 95 deberá ser menor a 0 (cero), - Cualquier otro caso deberá ser mayor o igual a 0 (cero).",
        [(Caea, 1120, false)] = "Si <codigoTipoComprobante> es igual a 1, 2, 3, 51, 52 o 53 y <codigoUnidadMedida> es distinto a 95, 97 ó 99 deberá ser igual a (<precioUnitario> sin IVA *<cantidad> -<importeBonificacion>)*(1+alícuota). Si <codigoTipoComprobante> es igual a 1, 2, 3, 51, 52 o 53 y <codigoUnidadMedida> es igual a 95 deberá ser igual a (-1) * (<precioUnitario> sin IVA * <cantidad> -<importeBonificacion>)*(1+alícuota). Si <codigoTipoComprobante> es igual a 6, 7 u 8 y <codigoUnidadMedida> es distinto a 95, 97 ó 99 deberá ser igual a (<precioUnitario> con IVA * <cantidad> - <importeBonificacion>). Si <codigoTipoComprobante> es igual a 6, 7 u 8 y <codigoUnidadMedida> es igual a 95 ser igual a (-1) * (<precioUnitario> con IVA * <cantidad> - <importeBonificacion>). En ambos casos el error relativo porcentual deberá ser <= 0.01% o el error absoluto <=0.01 *",
        [(Caea, 1122, false)] = "Si <codigoCondicionIVA> es igual a 1, 2, 3, 51, 52 o 53 entonces <importeIVA> deberá ser igual a 0 (cero).",
